# ====================================================================
# Documentation generation
# ====================================================================

class Config:
    """Doxygen configuration."""

    DEFAULTS = None

    def __init__(self, data=None):
        if Config.DEFAULTS is None:
            Config.DEFAULTS = get_default_config()
        self.data = dict(Config.DEFAULTS)
        if data:
            self.data.update(data)

    def get(self, key, default=None):
        val = self.data.get(key, [''])
        if not val or val == ['']:
            if default is not None:
                return default
            return ''
        # Single value - return as string
        if len(val) == 1:
            v = val[0]
            # Strip surrounding quotes
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1]
            return v
        # Multi value
        result = []
        for v in val:
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1]
            result.append(v)
        return result

    def get_bool(self, key, default=False):
        val = self.get(key)
        if isinstance(val, list):
            val = val[0] if val else ''
        return val.upper() == 'YES'

    def get_int(self, key, default=0):
        val = self.get(key)
        if isinstance(val, list):
            val = val[0] if val else ''
        try:
            return int(val)
        except:
            return default

    def get_list(self, key):
        val = self.data.get(key, [''])
        if not val or val == ['']:
            return []
        result = []
        for v in val:
            if v.startswith('"') and v.endswith('"'):
                v = v[1:-1]
            if v:
                result.append(v)
        return result

PYEOF

