cat > doxygen_docgen.py << 'PYEOF'
#!/usr/bin/env python3
"""
Doxygen documentation generation engine.
"""

import sys
import os
import re
import hashlib
import shutil
import glob
import fnmatch
from pathlib import Path
from datetime import datetime

# Import shared utilities
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from doxygen_impl import (
    VERSION, VERSION_FULL, VERSION_HASH, read_template, TEMPLATES_DIR,
    parse_doxyfile, get_default_config, Config
)

SCRIPT_DIR = Path(__file__).parent
HTML_RESOURCES = SCRIPT_DIR / "src" / "templates" / "html_resources"

# =====================================================================
# File name utilities
# =====================================================================

def escape_filename(name):
    """Convert a filename to Doxygen's output filename format.

    Rules: _ -> __, . -> _8, other special chars -> _XX
    """
    result = ''
    for c in name:
        if c.isalnum():
            result += c
        elif c == '_':
            result += '__'
        elif c == '.':
            result += '_8'
        elif c == '/':
            result += '_2f'
        elif c == ':':
            result += '_1'
        elif c == '-':
            result += '-'
        elif c == ' ':
            result += '_01'
        else:
            result += f'_{ord(c):02x}'
    return result

def dir_hash(path):
    """Compute the directory ID hash (MD5 of path without leading / but with trailing /)."""
    p = path.lstrip('/')
    if not p.endswith('/'):
        p += '/'
    return hashlib.md5(p.encode()).hexdigest()

def member_anchor_hash(qualified_name, args_string):
    """
    Compute the member anchor hash.
    Returns the 32-char hex hash (without leading 'a').

    Note: This is Doxygen's internal algorithm which we approximate.
    """
    # Use the same key as Doxygen's internal computation
    # We use MD5(qualifiedName + argsString) as our best approximation
    key = qualified_name + args_string
    return hashlib.md5(key.encode()).hexdigest()

def compound_id_for_class(class_name):
    """Get the compound ID for a class (e.g., Calculator -> classCalculator)."""
    escaped = escape_class_name(class_name)
    return 'class' + escaped

def compound_id_for_file(filename):
    """Get the compound ID for a file (e.g., test.cpp -> test_8cpp)."""
    basename = os.path.basename(filename)
    return escape_filename(basename)

def compound_id_for_namespace(ns_name):
    """Get the compound ID for a namespace."""
    return 'namespace' + escape_class_name(ns_name)

def escape_class_name(name):
    """Escape a class/namespace name for use in compound IDs."""
    result = ''
    for c in name:
        if c.isalnum() or c == '_':
            result += c
        elif c == ':':
            result += '_1'
        else:
            result += f'_{ord(c):02x}'
    return result

# =====================================================================
# C/C++ Comment Parser
# =====================================================================

class DocComment:
    """Represents a parsed Doxygen documentation comment."""

    def __init__(self):
        self.brief = ''
        self.detail = ''
        self.params = {}  # name -> description
        self.returns = ''
        self.author = ''
        self.version = ''
        self.date = ''
        self.file_doc = False
        self.file_brief = ''
        self.deprecated = ''
        self.since = ''
        self.note = ''
        self.warning = ''
        self.see = []
        self.todo = ''
        self.bug = ''
        self.pre = ''
        self.post = ''
        self.ingroup = ''
        self.tparam = {}
        self.throws = {}
        self.exception = {}
        self.raw_params = []

    def __bool__(self):
        return bool(self.brief or self.detail or self.params or self.returns)

def parse_doc_comment(text):
    """Parse a Doxygen comment block into a DocComment object."""
    doc = DocComment()

    # Clean up the comment text
    # Remove leading * from each line
    lines = []
    for line in text.split('\n'):
        line = line.strip()
        if line.startswith('*'):
            line = line[1:].strip()
        elif line.startswith('//!') or line.startswith('///'):
            line = line[3:].strip()
        lines.append(line)

    # Parse the content
    current_tag = 'brief'
    current_content = []

    for line in lines:
        # Check for @ or \ tags
        m = re.match(r'^[@\\]([\w]+)\s*(.*)', line)
        if m:
            tag = m.group(1).lower()
            content = m.group(2).strip()

            # Save previous content
            if current_content:
                text_block = ' '.join(current_content).strip()
                _store_tag(doc, current_tag, text_block)
                current_content = []

            current_tag = tag
            if content:
                current_content = [content]

            # Handle special tags
            if tag in ('param', 'param[in]', 'param[out]', 'param[in,out]'):
                # @param name description
                pm = re.match(r'(?:\[.*?\])?\s*(\w+)\s*(.*)', content)
                if pm:
                    param_name = pm.group(1)
                    param_desc = pm.group(2).strip()
                    doc.raw_params.append((param_name, param_desc))
                    current_tag = f'param:{param_name}'
                    current_content = [param_desc] if param_desc else []
            elif tag in ('tparam',):
                pm = re.match(r'(\w+)\s*(.*)', content)
                if pm:
                    param_name = pm.group(1)
                    param_desc = pm.group(2).strip()
                    current_tag = f'tparam:{param_name}'
                    current_content = [param_desc] if param_desc else []
            elif tag in ('throw', 'throws', 'exception'):
                pm = re.match(r'(\w+)\s*(.*)', content)
                if pm:
                    exc_name = pm.group(1)
                    exc_desc = pm.group(2).strip()
                    doc.throws[exc_name] = exc_desc
                    current_tag = None
                    current_content = []
            elif tag == 'file':
                doc.file_doc = True
                current_tag = 'brief'
            elif tag == 'return' or tag == 'returns':
                current_tag = 'return'
            elif tag == 'brief':
                current_tag = 'brief'
            elif tag == 'details' or tag == 'detail':
                current_tag = 'detail'
            elif tag == 'author':
                doc.author = content
                current_tag = None
                current_content = []
            elif tag == 'version':
                doc.version = content
                current_tag = None
                current_content = []
            elif tag == 'date':
                doc.date = content
                current_tag = None
                current_content = []
            elif tag == 'deprecated':
                current_tag = 'deprecated'
            elif tag == 'since':
                current_tag = 'since'
            elif tag == 'note':
                current_tag = 'note'
            elif tag == 'warning':
                current_tag = 'warning'
            elif tag in ('see', 'sa'):
                doc.see.append(content)
                current_tag = None
                current_content = []
            elif tag == 'todo':
                current_tag = 'todo'
            elif tag == 'bug':
                current_tag = 'bug'
            elif tag == 'pre':
                current_tag = 'pre'
            elif tag == 'post':
                current_tag = 'post'
            elif tag == 'ingroup':
                doc.ingroup = content
