                doc.file_doc = True
                current_tag = 'brief'
            elif tag == 'return' or tag == 'returns':
                current_tag = 'return'
            elif tag == 'brief':
                current_tag = 'brief'
            elif tag == 'details' or tag == 'detail':
                current_tag = 'detail'
            elif tag == 'author':
                doc.author = content
                current_tag = None
                current_content = []
            elif tag == 'version':
                doc.version = content
                current_tag = None
                current_content = []
            elif tag == 'date':
                doc.date = content
                current_tag = None
                current_content = []
            elif tag == 'deprecated':
                current_tag = 'deprecated'
            elif tag == 'since':
                current_tag = 'since'
            elif tag == 'note':
                current_tag = 'note'
