    elif tag == 'detail':
        doc.detail = text if not doc.detail else doc.detail + '\n' + text
    elif tag == 'deprecated':
        doc.deprecated = text
    elif tag == 'since':
        doc.since = text
    elif tag == 'note':
        doc.note = text
    elif tag == 'warning':
        doc.warning = text
    elif tag == 'todo':
        doc.todo = text
    elif tag == 'bug':
        doc.bug = text
    elif tag and tag.startswith('param:'):
